corporate_design.toad_component_blueprint:
canvas {
  size: 880px 560px;
  fill: #18181B;
  font-family: "Inter, sans-serif";
}

>lime = #84CC16;
>white = #FFFFFF;

rect #veloCard {
  at: center of canvas;
  size: 780px 460px;
  fill: #27272A;
  stroke: >lime;
  stroke-width: 2px;
  radius: 16px;
}

text #veloHeader {
  at: top left of #veloCard offset 36px 36px;
  content: "VELOCITY // 2.500 E-BIKES AN 200 STATIONEN";
  font-size: 13px;
  font-weight: 800;
  color: >lime;
}

text #veloTitle {
  at: below #veloHeader offset 14px;
  content: "Entsperren. Losradeln. Die Stadt gehört Dir.";
  font-size: 32px;
  font-weight: 800;
  color: >white;
}
